macro_rules! rustc_unescape_error_to_string {
    () => {
        fn rustc_unescape_error_to_string (err : EscapeError) -> (& 'static str , bool) { use EscapeError as EE ; # [rustfmt :: skip] let err_message = match err { EE :: ZeroChars => { "Literal must not be empty" } EE :: MoreThanOneChar => { "Literal must be one character long" } EE :: LoneSlash => { "Character must be escaped: `\\`" } EE :: InvalidEscape => { "Invalid escape" } EE :: BareCarriageReturn | EE :: BareCarriageReturnInRawString => { "Character must be escaped: `\r`" } EE :: EscapeOnlyChar => { "Escape character `\\` must be escaped itself" } EE :: TooShortHexEscape => { "ASCII hex escape code must have exactly two digits" } EE :: InvalidCharInHexEscape => { "ASCII hex escape code must contain only hex characters" } EE :: OutOfRangeHexEscape => { "ASCII hex escape code must be at most 0x7F" } EE :: NoBraceInUnicodeEscape => { "Missing `{` to begin the unicode escape" } EE :: InvalidCharInUnicodeEscape => { "Unicode escape must contain only hex characters and underscores" } EE :: EmptyUnicodeEscape => { "Unicode escape must not be empty" } EE :: UnclosedUnicodeEscape => { "Missing `}` to terminate the unicode escape" } EE :: LeadingUnderscoreUnicodeEscape => { "Unicode escape code must not begin with an underscore" } EE :: OverlongUnicodeEscape => { "Unicode escape code must have at most 6 digits" } EE :: LoneSurrogateUnicodeEscape => { "Unicode escape code must not be a surrogate" } EE :: OutOfRangeUnicodeEscape => { "Unicode escape code must be at most 0x10FFFF" } EE :: UnicodeEscapeInByte => { "Byte literals must not contain unicode escapes" } EE :: NonAsciiCharInByte => { "Byte literals must not contain non-ASCII characters" } EE :: NulInCStr => { "C strings literals must not contain null characters" } EE :: UnskippedWhitespaceWarning => "Whitespace after this escape is not skipped" , EE :: MultipleSkippedLinesWarning => "Multiple lines are skipped by this escape" , } ; (err_message , err . is_fatal ()) }
    };
}

rustc_unescape_error_to_string!();